17	/* Microphone uplink: AUDCODEC capture -> binary WebSocket frames.
18	 *
19	 * One thread per stream. It owns the codec for as long as it runs, so the
20	 * bring-up commands (mic_test and friends) must not be used concurrently.
21	 */
22	
23	#include "channels/mic_stream.h"
24	#include "channels/ws_server.h"
25	#include "agent_compat.h"
26	
27	#include "sf32lb_audcodec.h"
28	
29	#include <pthread.h>
30	#include <stdio.h>
31	#include <string.h>
32	#include <unistd.h>
33	
34	#ifdef CONFIG_SF32LB52_AUDCODEC
35	
36	/* 5 kHz, G.711 mu-law, one byte per sample.
37	 *
38	 * Both numbers are set by what the link can carry. The serial connection
39	 * under this board's PPP link sustains about 5.2 KB/s of payload; 16 kHz of
40	 * 16-bit mono needs 32 KB/s and 8 kHz of mu-law needs 8 KB/s, and neither
41	 * overrun degrades gracefully -- the reader falls behind, the DMA ring laps,
42	 * and the gaps come out as aliasing that no recogniser can read. 5 kHz of
43	 * mu-law is 5 KB/s and arrives contiguous.
44	 */
45	
46	#define MIC_STREAM_RATE    2667
47	
48	static pthread_t s_thread;
49	static volatile bool s_running;
50	static bool s_started;
51	static char s_chat_id[64];
52	static int  s_samples = MIC_STREAM_DEF_SAMPLES;
53	
54	/* Static rather than stack: the streaming thread only needs a small stack,
55	 * and this keeps it that way.
56	 */
57	
58	static int16_t s_block[MIC_STREAM_MAX_SAMPLES];
59	static uint8_t s_ulaw[MIC_STREAM_MAX_SAMPLES];
60	
61	/****************************************************************************
62	 * Name: mic_ulaw_encode
63	 *
64	 * Description:
65	 *   ITU-T G.711 mu-law companding. Quantisation is logarithmic because
66	 *   speech spends most of its time at low amplitude, and a linear 8-bit
67	 *   representation throws away the very part that carries the words.
68	 *
69	 ****************************************************************************/
70	
71	static uint8_t mic_ulaw_encode(int16_t pcm)
72	{
73	    const int bias = 0x84;
74	    const int clip = 32635;
75	    int sample = pcm;          /* int: -(-32768) has to fit */
76	    int sign = 0;
77	    int exponent = 7;
78	    int mantissa;
79	    int mask;
80	
81	    if (sample < 0) {
82	        sample = -sample;
83	        sign = 0x80;
84	    }
85	
86	    if (sample > clip) {
87	        sample = clip;
88	    }
89	
90	    sample += bias;
91	
92	    /* Segment count: how many bits below bit 14 are needed to reach the
93	     * leading one. */
94	    for (mask = 0x4000; exponent > 0 && (sample & mask) == 0; mask >>= 1) {
95	        exponent--;
96	    }
97	
98	    mantissa = (sample >> (exponent + 3)) & 0x0f;
99	
100	    return (uint8_t)(~(sign | (exponent << 4) | mantissa));
101	}
102	
103	static void* mic_stream_thread(void* arg)
104	{
105	    (void)arg;
106	
107	    syslog(LOG_INFO, "[mic_stream] capture starting for %s\n", s_chat_id);
108	
109	    /* Tell the far end what the bytes mean before sending any. A recogniser
110	     * fed the wrong rate or the wrong codec does not fail loudly, it just
111	     * produces confident nonsense, so the format travels with the stream. */
112	    {
113	        char fmt[96];
114	        snprintf(fmt, sizeof(fmt),
115	            "{\"type\":\"audio_format\",\"codec\":\"ulaw\",\"rate\":%d,"
116	            "\"channels\":1}", MIC_STREAM_RATE);
117	        ws_server_send_json(s_chat_id, fmt);
118	    }
119	
120	    if (!sf32lb_audcodec_is_open()) {
121	        int ret = sf32lb_audcodec_open(MIC_STREAM_RATE);
122	        if (ret < 0) {
123	            syslog(LOG_ERR, "[mic_stream] open failed (%d)\n", ret);
124	            s_running = false;
125	            return NULL;
126	        }
127	    }
128	
129	    while (s_running) {
130	        ssize_t n = sf32lb_audcodec_read(s_block, (size_t)s_samples);
131	        ssize_t i;
132	
133	        if (n < 0) {
134	            syslog(LOG_ERR, "[mic_stream] capture read failed (%d)\n", (int)n);
135	            break;
136	        }
137	
138	        for (i = 0; i < n; i++) {
139	            s_ulaw[i] = mic_ulaw_encode(s_block[i]);
140	        }
141	
142	        /* A failed send means the client went away; stop rather than spin. */
143	        if (ws_server_send_binary(s_chat_id, s_ulaw, (size_t)n) != OK) {
144	            syslog(LOG_WARNING, "[mic_stream] send failed, stopping\n");
145	            break;
146	        }
147	    }
148	
149	    sf32lb_audcodec_close();
150	    s_running = false;
151	
152	    syslog(LOG_INFO, "[mic_stream] capture stopped\n");
153	    return NULL;
154	}
155	
156	int mic_stream_start(const char* chat_id, int samples)
157	{
158	    if (s_running) {
159	        return OK; /* already streaming */
160	    }
161	
162	    if (chat_id == NULL || chat_id[0] == '\0') {
163	        return ERROR;
164	    }
165	
166	    if (samples <= 0) {
167	        samples = MIC_STREAM_DEF_SAMPLES;
168	    } else if (samples > MIC_STREAM_MAX_SAMPLES) {
169	        samples = MIC_STREAM_MAX_SAMPLES;
170	    }
171	
172	    s_samples = samples;
173	
174	    strncpy(s_chat_id, chat_id, sizeof(s_chat_id) - 1);
175	    s_chat_id[sizeof(s_chat_id) - 1] = '\0';
176	
177	    syslog(LOG_INFO, "[mic_stream] chunk = %d samples (%d bytes)\n",
178	        s_samples, s_samples * 2);
179	
180	    s_running = true;
181	
182	    pthread_attr_t attr;
183	    pthread_attr_init(&attr);
184	    pthread_attr_setstacksize(&attr, 4096);
185	
186	    int ret = pthread_create(&s_thread, &attr, mic_stream_thread, NULL);
187	    pthread_attr_destroy(&attr);
188	
189	    if (ret != 0) {
190	        s_running = false;
191	        syslog(LOG_ERR, "[mic_stream] pthread_create failed (%d)\n", ret);
192	        return ERROR;
193	    }
194	
195	    s_started = true;
196	    return OK;
197	}
198	
199	int mic_stream_stop(void)
200	{
201	    if (!s_running && !s_started) {
202	        return OK;
203	    }
204	
205	    s_running = false;
206	
207	    /* The thread notices s_running within one 100 ms block. */
208	    pthread_join(s_thread, NULL);
209	    s_started = false;
210	
211	    return OK;
212	}
213	
214	bool mic_stream_is_running(void)
215	{
216	    return s_running;
217	}
218	
219	#else /* !CONFIG_SF32LB52_AUDCODEC */
220	
221	int mic_stream_start(const char* chat_id, int samples)
222	{
223	    (void)chat_id;
224	    (void)samples;
225	    return ERROR;
226	}
227	
228	int mic_stream_stop(void)
229	{
230	    return OK;
231	}
232	
233	bool mic_stream_is_running(void)
234	{
235	    return false;
236	}
237	
238	#endif /* CONFIG_SF32LB52_AUDCODEC */
