1	/****************************************************************************
2	 * vendor/sifli/chips/sf32lb52/sf32lb_audcodec.c
3	 *
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * SF32LB52 AUDCODEC ADC capture path (on-board MEMS microphone).
7	 *
8	 * Bring-up notes, because the vendor HAL leaves all of this to the caller:
9	 *
10	 *   - SF32LB52X builds bf0_hal_audcodec_m.c, not bf0_hal_audcodec.c.
11	 *   - HAL_AUDCODEC_MspInit() is empty: no clock, pin or DMA setup happens
12	 *     for us. HAL_DMA_Init() is invoked by HAL_AUDCODEC_Init() through
13	 *     HAL_AUDCODEC_DMA_Init(), but only after the caller has filled in
14	 *     Instance and Init.Request on the DMA handle.
15	 *   - HAL_AUDCODEC_Config_ADCPath() is compiled out (#if 0), so the analog
16	 *     front end is set up with HAL_AUDCODEC_Config_Analog_ADCPath(), which
17	 *     also enables the microphone bias.
18	 *   - The ADC needs the audio PLL: ADC_CFG.CLK_SRC_SEL is programmed to 1.
19	 *
20	 * Capture is a plain circular DMA into a single buffer; the reader derives
21	 * the DMA write position from CNDTR, so no DMA interrupt handler has to run
22	 * at audio rate and a reader that falls behind loses samples rather than
23	 * stalling the capture path.
24	 *
25	 ****************************************************************************/
26	
27	/****************************************************************************
28	 * Included Files
29	 ****************************************************************************/
30	
31	#include <nuttx/config.h>
32	
33	#include <debug.h>
34	#include <errno.h>
35	#include <stdbool.h>
36	#include <stdint.h>
37	#include <string.h>
38	#include <syslog.h>
39	#include <unistd.h>
40	
41	#include <nuttx/arch.h>
42	#include <nuttx/cache.h>
43	#include <nuttx/clock.h>
44	
45	#include "bf0_hal.h"
46	#include "bf0_hal_audcodec.h"
47	#include "dma_config.h"
48	
49	#include "sf32lb_audcodec.h"
50	
51	/****************************************************************************
52	 * Pre-processor Definitions
53	 ****************************************************************************/
54	
55	/* Words of circular DMA buffer; see SF32LB_AUDIO_DMA_WORDS. Must be a power
56	 * of two: the write position is masked rather than wrapped.
57	 */
58	
59	#define MIC_DMA_WORDS    SF32LB_AUDIO_DMA_WORDS
60	#define MIC_DMA_BYTES    (MIC_DMA_WORDS * 4)
61	#define MIC_DMA_MASK     (MIC_DMA_WORDS - 1)
62	
63	/* Poll interval while waiting for the DMA to advance. */
64	
65	#define MIC_POLL_US      2000
66	
67	/* Give up on a read after this many consecutive polls with no DMA progress
68	 * (2000 us each, so ~2 s). Guards against wedging the caller when the ADC is
69	 * silent, which is the expected symptom of a misconfigured capture path.
70	 */
71	
72	#define MIC_STALL_LIMIT  1000
73	
74	/* Nominal rate used when bringing the PLL up. bf0_enable_pll() type 0 selects
75	 * the 1024-series frequency, 49.152 MHz == 16000 * 3072.
76	 */
77	
78	#define MIC_SAMPLE_RATE  16000
79	
80	/* The audible rate is set by g_clk_div / g_osr_sel, not by this parameter,
81	 * so it is only a sanity bound: the caller states what it believes the rate
82	 * to be and the driver refuses values that cannot be right.
83	 */
84	
85	#define MIC_RATE_MIN     2000
86	#define MIC_RATE_MAX     48000
87	
88	/****************************************************************************
89	 * Private Data
90	 ****************************************************************************/
91	
92	/* The DMA target. Aligned so that the cache maintenance below operates on
93	 * whole cache lines.
94	 */
95	
96	static uint32_t g_dma_buf[MIC_DMA_WORDS] aligned_data(32);
97	
98	static DMA_HandleTypeDef      g_hdma_adc;
99	static AUDCODEC_HandleTypeDef g_codec;
100	static bool                   g_open;
101	static uint32_t               g_did;      /* HAL_AUDCODEC_ADC_CH0/CH1 */
102	static bool                   g_pll;      /* audio PLL was enabled */
103	
104	/* ADC_CFG divider and OSR.
105	 *
106	 * Calibrated by measurement, not derived: nothing in the tree documents how
107	 * these two fields map onto a sample rate, and the values the HAL ships with
108	 * (5 / 0) actually produce about 20 kHz. Measured rates, PLL clock source:
109	 *
110	 *     clk_div/osr_sel   5/0    6/0    7/0    8/0    9/0    12/0
111	 *     Hz                19986  19851  15920  13333  11431  10000
112	 *
113	 *     clk_div/osr_sel   7/1    9/1    8/3    7/3    9/3
114	 *     Hz                10000  8000   5000   5333   4211
115	 *
116	 * The default is 8 / 3 == 5 kHz, chosen to match what the transport can
117	 * actually carry rather than what the ADC would like to produce. The serial
118	 * link under this board's PPP connection sustains about 5.2 KB/s of payload,
119	 * so 8 kHz of mu-law (8 KB/s) still overruns it -- and overrunning it does
120	 * not degrade gracefully: the reader falls behind, the DMA ring laps, and the
121	 * samples that go missing are replaced by whatever came 2 s later. Matching
122	 * the rates is what keeps the audio contiguous.
123	 *
124	 * Re-check with mic_rate if the PLL frequency or the clock source changes.
125	 */
126	
127	static uint8_t                g_clk_div = 15;
128	static uint8_t                g_osr_sel = 3;
129	
130	void sf32lb_audcodec_set_clk(uint8_t clk_div, uint8_t osr_sel)
131	{
132	  g_clk_div = clk_div;
133	  g_osr_sel = (uint8_t)(osr_sel & 0x3);
134	}
135	
136	void sf32lb_audcodec_get_clk(uint8_t *clk_div, uint8_t *osr_sel)
137	{
138	  if (clk_div != NULL)
139	    {
140	      *clk_div = g_clk_div;
141	    }
142	
143	  if (osr_sel != NULL)
144	    {
145	      *osr_sel = g_osr_sel;
146	    }
147	}
148	
149	/****************************************************************************
150	 * Private Functions
151	 ****************************************************************************/
152	
153	/****************************************************************************
154	 * Name: mic_dma_pos
155	 *
156	 * Description:
157	 *   Current DMA write position, in words, within the circular buffer.
158	 *   CNDTR counts down as transfers complete, so the number of words already
159	 *   written is MIC_DMA_WORDS - CNDTR. When CNDTR has just reloaded the
160	 *   position reads back as MIC_DMA_WORDS, which the mask maps to 0.
161	 *
162	 ****************************************************************************/
163	
164	static unsigned int mic_dma_pos(void)
165	{
166	  return (MIC_DMA_WORDS - __HAL_DMA_GET_COUNTER(&g_hdma_adc)) & MIC_DMA_MASK;
167	}
168	
169	/****************************************************************************
170	 * Name: mic_dma_start
171	 *
172	 * Description:
173	 *   Fill in the DMA handle and the codec handle, then let the HAL arm the
174	 *   channel. Instance and Init.Request are the caller's job; everything
175	 *   else is overwritten by HAL_AUDCODEC_DMA_Init().
176	 *
177	 ****************************************************************************/
178	
179	static int mic_dma_start(void)
180	{
181	  memset(&g_hdma_adc, 0, sizeof(g_hdma_adc));
182	  memset(&g_codec, 0, sizeof(g_codec));
183	
184	  g_hdma_adc.Instance         = AUDCODEC_ADC0_DMA_INSTANCE;
185	  g_hdma_adc.Init.Request     = AUDCODEC_ADC0_DMA_REQUEST;
186	  g_hdma_adc.Init.IrqPrio     = AUDCODEC_ADC0_DMA_IRQ_PRIO;
187	
188	  g_codec.Instance            = hwp_audcodec;
189	  g_codec.hdma[HAL_AUDCODEC_ADC_CH0] = &g_hdma_adc;
190	
191	  /* HAL_AUDCODEC_Init() runs HAL_AUDCODEC_DMA_Init() over hdma[], which is
192	   * what actually calls HAL_DMA_Init().
193	   */
194	
195	  if (HAL_AUDCODEC_Init(&g_codec) != HAL_OK)
196	    {
197	      _err("ERROR: HAL_AUDCODEC_Init failed\n");
198	      return -EIO;
199	    }
200	
201	  return OK;
202	}
203	
204	/****************************************************************************
205	 * Public Functions
206	 ****************************************************************************/
207	
208	/* Not declared in bf0_hal_audcodec.h even though it is exported, so pull it
209	 * in here rather than duplicating the rough/fine volume encoding.
210	 */
211	
212	extern HAL_StatusTypeDef
213	HAL_AUDCODEC_Config_ADCPath_Volume(AUDCODEC_HandleTypeDef *hacodec,
214	                                   int channel, int volume);
215	
216	int sf32lb_audcodec_open_ex(uint32_t sample_rate,
217	                            enum sf32lb_audio_clk_e clk, int channel,
218	                            int volume_db)
219	{
220	  AUDCODE_ADC_CLK_CONFIG_TYPE adc_clk;
221	  AUDCODEC_ADCCfgTypeDef      adc_cfg;
222	  int                         ret;
223	  int                         use_pll = (clk == SF32LB_AUDIO_CLK_PLL);
224	
225	  if (g_open)
226	    {
227	      return -EBUSY;
228	    }
229	
230	  if (sample_rate < MIC_RATE_MIN || sample_rate > MIC_RATE_MAX)
231	    {
232	      _err("ERROR: implausible capture rate %lu (expected %u..%u)\n",
233	           (unsigned long)sample_rate, MIC_RATE_MIN, MIC_RATE_MAX);
234	      return -EINVAL;
235	    }
236	
237	  if (channel != 0 && channel != 1)
238	    {
239	      _err("ERROR: ADC channel must be 0 or 1 (asked for %d)\n", channel);
240	      return -EINVAL;
241	    }
242	
243	  memset(g_dma_buf, 0, sizeof(g_dma_buf));
244	
245	  if (use_pll && bf0_enable_pll(MIC_SAMPLE_RATE, 0) != 0)
246	    {
247	      _err("ERROR: bf0_enable_pll failed (audio PLL did not lock)\n");
248	      return -EIO;
249	    }
250	
251	  ret = mic_dma_start();
252	  if (ret < 0)
253	    {
254	      if (use_pll)
255	        {
256	          bf0_disable_pll();
257	        }
258	
259	      return ret;
260	    }
261	
262	  /* clk_div 5 and osr_sel 0 reproduce the reference configuration the HAL
263	   * documents as ADC_CFG == 0x508 (OP_MODE 1). Note that 0x508 has
264	   * CLK_SRC_SEL == 0, i.e. the 48 MHz crystal rather than the PLL, so the
265	   * clock source is caller-selectable.
266	   */
267	
268	  memset(&adc_clk, 0, sizeof(adc_clk));
269	  adc_clk.samplerate         = MIC_SAMPLE_RATE;
270	  adc_clk.clk_src_sel        = (uint8_t)(use_pll ? 1 : 0);
271	  adc_clk.clk_div            = g_clk_div;
272	  adc_clk.osr_sel            = g_osr_sel;
273	  adc_clk.sel_clk_adc_source = (uint8_t)(use_pll ? 1 : 0);
274	  adc_clk.sel_clk_adc        = 1;
275	  adc_clk.diva_clk_adc       = 5;
276	  adc_clk.fsp                = 0;
277	
278	  adc_cfg.opmode  = 1;
279	  adc_cfg.adc_clk = &adc_clk;
280	
281	  if (HAL_AUDCODEC_Config_RChanel(&g_codec, channel, &adc_cfg) != HAL_OK)
282	    {
283	      _err("ERROR: HAL_AUDCODEC_Config_RChanel failed\n");
284	      ret = -EIO;
285	      goto err_out;
286	    }
287	
288	  g_did = (channel == 0) ? HAL_AUDCODEC_ADC_CH0 : HAL_AUDCODEC_ADC_CH1;
289	
290	  /* Gain, after the channel config that resets these fields. */
291	
292	  if (volume_db < SF32LB_AUDIO_VOLUME_MIN)
293	    {
294	      volume_db = SF32LB_AUDIO_VOLUME_MIN;
295	    }
296	
297	  if (volume_db > SF32LB_AUDIO_VOLUME_MAX)
298	    {
299	      volume_db = SF32LB_AUDIO_VOLUME_MAX;
300	    }
301	
302	  if (HAL_AUDCODEC_Config_ADCPath_Volume(&g_codec, channel, volume_db)
303	      != HAL_OK)
304	    {
305	      _err("ERROR: HAL_AUDCODEC_Config_ADCPath_Volume failed\n");
306	    }
307	
308	  /* Make sure stale cache lines are not what the reader ends up seeing. */
309	
310	  up_invalidate_dcache((uintptr_t)g_dma_buf,
311	                       (uintptr_t)g_dma_buf + sizeof(g_dma_buf));
312	
313	  if (HAL_AUDCODEC_Receive_DMA(&g_codec, (uint8_t *)g_dma_buf,
314	                               MIC_DMA_BYTES, g_did) != HAL_OK)
315	    {
316	      _err("ERROR: HAL_AUDCODEC_Receive_DMA failed\n");
317	      ret = -EIO;
318	      goto err_out;
319	    }
320	
321	  /* Reference generator. This is the piece the vendor HAL leaves to its
322	   * caller and that nothing else in the tree calls: without REFGEN_CFG.EN
323	   * the converter has no reference to compare against and every sample
324	   * comes back as zero, with the DMA running happily the whole time.
325	   */
326	
327	  HAL_AUCODEC_Refgen_Init();
328	
329	  /* Analog front end. This switches the microphone bias on and brings
330	   * ADC1/ADC2 out of reset; it blocks for ~20 ms internally.
331	   */
332	
333	  HAL_AUDCODEC_Config_Analog_ADCPath(&adc_clk);
334	
335	  /* Finally turn the ADC block on. The HAL never does this itself: both
336	   * call sites in bf0_hal_audcodec_m.c are commented out and only the
337	   * disable path is live.
338	   */
339	
340	  __HAL_AUDCODEC_ADC_ENABLE(&g_codec);
341	
342	  g_open = true;
343	  g_pll  = use_pll;
344	
345	  syslog(LOG_INFO,
346	         "[audcodec] mic capture started: %lu Hz nominal, div=%u osr=%u, "
347	         "ch%d %s clk, %u-word DMA ring\n",
348	         (unsigned long)sample_rate, g_clk_div, g_osr_sel, channel,
349	         use_pll ? "PLL" : "xtal", (unsigned)MIC_DMA_WORDS);
350	
351	  return OK;
352	
353	err_out:
354	  __HAL_AUDCODEC_ADC_DISABLE(&g_codec);
355	  HAL_AUDCODEC_Close_Analog_ADCPath();
356	  HAL_AUDCODEC_Clear_All_Channel(&g_codec, 0x2);
357	
358	  if (use_pll)
359	    {
360	      bf0_disable_pll();
361	    }
362	
363	  return ret;
364	}
365	
366	int sf32lb_audcodec_open(uint32_t sample_rate)
367	{
368	  return sf32lb_audcodec_open_ex(sample_rate, SF32LB_AUDIO_CLK_PLL, 0,
369	                                 SF32LB_AUDIO_DEFAULT_VOLUME);
370	}
371	
372	/****************************************************************************
373	 * Name: mic_copy_words
374	 *
375	 * Description:
376	 *   Copy 'words' words out of the circular DMA buffer starting at 'first',
377	 *   splitting the copy when the range wraps.
378	 *
379	 ****************************************************************************/
380	
381	static void mic_copy_words(uint32_t *dst, unsigned int first,
382	                           unsigned int words)
383	{
384	  unsigned int head;
385	
386	  up_invalidate_dcache((uintptr_t)&g_dma_buf[first],
387	                       (uintptr_t)&g_dma_buf[first] + words * sizeof(uint32_t));
388	
389	  head = MIC_DMA_WORDS - first;
390	  if (head >= words)
391	    {
392	      memcpy(dst, &g_dma_buf[first], words * sizeof(uint32_t));
393	      return;
394	    }
395	
396	  memcpy(dst, &g_dma_buf[first], head * sizeof(uint32_t));
397	  memcpy(dst + head, g_dma_buf, (words - head) * sizeof(uint32_t));
398	}
399	
400	ssize_t sf32lb_audcodec_read_raw(uint32_t *buf, size_t words)
401	{
402	  size_t       got    = 0;
403	  unsigned int last;
404	  unsigned int stalls = 0;
405	
406	  if (!g_open)
407	    {
408	      return -EINVAL;
409	    }
410	
411	  last = mic_dma_pos();
412	
413	  while (got < words)
414	    {
415	      unsigned int now = mic_dma_pos();
416	      unsigned int avail;
417	
418	      if (now == last)
419	        {
420	          if (++stalls > MIC_STALL_LIMIT)
421	            {
422	              _err("ERROR: DMA stalled at word %u, no audio from the ADC\n",
423	                   last);
424	              return got > 0 ? (ssize_t)got : -ETIMEDOUT;
425	            }
426	
427	          usleep(MIC_POLL_US);
428	          continue;
429	        }
430	
431	      stalls = 0;
432	
433	      avail = (now - last) & MIC_DMA_MASK;
434	      if (avail > words - got)
435	        {
436	          avail = words - got;
437	        }
438	
439	      mic_copy_words(buf + got, last, avail);
440	
441	      got += avail;
442	      last = (last + avail) & MIC_DMA_MASK;
443	    }
444	
445	  return (ssize_t)got;
446	}
447	
448	ssize_t sf32lb_audcodec_read(int16_t *buf, size_t samples)
449	{
450	  size_t       got    = 0;
451	  unsigned int last;
452	  unsigned int stalls = 0;
453	
454	  if (!g_open)
455	    {
456	      return -EINVAL;
457	    }
458	
459	  /* A request that spans the whole ring cannot be served: the write position
460	   * is tracked modulo the ring, so an advance of exactly one ring is
461	   * indistinguishable from no advance, and the caller would wait forever on a
462	   * capture path that is working perfectly. */
463	
464	  if (samples >= MIC_DMA_WORDS)
465	    {
466	      _err("ERROR: request %u samples but the DMA ring holds only %u\n",
467	           (unsigned)samples, (unsigned)MIC_DMA_WORDS);
468	      return -EINVAL;
469	    }
470	
471	  last = mic_dma_pos();
472	
473	  while (got < samples)
474	    {
475	      unsigned int now = mic_dma_pos();
476	      unsigned int avail;
477	      unsigned int i;
478	
479	      if (now == last)
480	        {
481	          /* Give up rather than wedge the caller forever if the ADC is
482	           * silent -- a capture path that never produces a sample is a
483	           * configuration bug, not something to wait out.
484	           */
485	
486	          if (++stalls > MIC_STALL_LIMIT)
487	            {
488	              _err("ERROR: DMA stalled at word %u, no audio from the ADC\n",
489	                   last);
490	              return got > 0 ? (ssize_t)got : -ETIMEDOUT;
491	            }
492	
493	          usleep(MIC_POLL_US);
494	          continue;
495	        }
496	
497	      stalls = 0;
498	
499	      avail = (now - last) & MIC_DMA_MASK;
500	      if (avail > samples - got)
501	        {
502	          avail = samples - got;
503	        }
504	
505	      /* The ADC drops one 16-bit sample into the low half of each 32-bit
506	       * DMA word; compact them so the caller sees packed mono PCM.
507	       */
508	
509	      up_invalidate_dcache((uintptr_t)&g_dma_buf[last],
510	                           (uintptr_t)&g_dma_buf[last] +
511	                           avail * sizeof(uint32_t));
512	
513	      for (i = 0; i < avail; i++)
514	        {
515	          unsigned int idx = (last + i) & MIC_DMA_MASK;
516	          buf[got + i] = (int16_t)(g_dma_buf[idx] & 0xffff);
517	        }
518	
519	      got += avail;
520	      last = (last + avail) & MIC_DMA_MASK;
521	    }
522	
523	  return (ssize_t)got;
524	}
