575	void sf32lb_audcodec_analyze(const int16_t *buf, size_t samples,
576	                             struct sf32lb_audio_stats_s *stats)
577	{
578	  int64_t sum  = 0;
579	  int64_t sum2 = 0;
580	  size_t  i;
581	
582	  stats->min   = 0;
583	  stats->max   = 0;
584	  stats->mean  = 0;
585	  stats->rms   = 0;
586	  stats->nzero = 0;
587	  stats->count = samples;
588	
589	  if (samples == 0)
590	    {
591	      return;
592	    }
593	
594	  stats->min = buf[0];
595	  stats->max = buf[0];
596	
597	  for (i = 0; i < samples; i++)
598	    {
599	      int32_t v = buf[i];
600	
601	      if (v < stats->min)
602	        {
603	          stats->min = v;
604	        }
605	
606	      if (v > stats->max)
607	        {
608	          stats->max = v;
609	        }
610	
611	      if (v == 0)
612	        {
613	          stats->nzero++;
614	        }
615	
616	      sum  += v;
617	      sum2 += (int64_t)v * v;
618	    }
619	
620	  stats->mean = (int32_t)(sum / (int64_t)samples);
621	  stats->rms  = (int32_t)__builtin_sqrt((double)sum2 / (double)samples);
622	}
