123	/* ── WS handshake ─────────────────────────────────────────────── */
124	
125	/**
126	 * Compute Sec-WebSocket-Accept = base64(SHA1(key + GUID))
127	 */
128	static int make_accept_key(const char* key, char* out, size_t out_size)
129	{
130	    char combined[256];
131	    int clen = snprintf(combined, sizeof(combined), "%s%s", key, WS_GUID);
132	    if (clen <= 0 || clen >= (int)sizeof(combined))
133	        return -1;
134	
135	    unsigned char sha[20];
136	    if (mbedtls_sha1((const unsigned char*)combined, (size_t)clen, sha) != 0)
137	        return -1;
138	
139	    size_t written = 0;
140	    if (mbedtls_base64_encode((unsigned char*)out, out_size, &written, sha,
141	            sizeof(sha))
142	        != 0)
143	        return -1;
144	    out[written] = '\0';
145	    return (int)written;
146	}
147	
148	/**
149	 * WebSocket handshake using pre-read buffer.
150	 * Read full HTTP upgrade request, extract Sec-WebSocket-Key.
151	 * Returns 0 on success; sends 101 response.
152	 */
153	static int do_ws_handshake_ex(int fd, const char* buf, int buf_len,
154	    char* chat_id_out, size_t chat_id_size)
155	{
156	
157	    /* Extract Sec-WebSocket-Key */
158	    char* key_hdr = strcasestr(buf, "\r\nSec-WebSocket-Key: ");
159	    if (!key_hdr) {
160	        syslog(LOG_WARNING, "[%s] No Sec-WebSocket-Key\n", TAG);
161	        return -1;
162	    }
163	    key_hdr += 21;
164	    char* eol = strstr(key_hdr, "\r\n");
165	    if (!eol)
166	        return -1;
167	
168	    char ws_key[128] = { 0 };
169	    size_t klen = (size_t)(eol - key_hdr);
170	    if (klen >= sizeof(ws_key))
171	        return -1;
172	    memcpy(ws_key, key_hdr, klen);
173	    ws_key[klen] = '\0';
174	
175	    /* Compute accept */
176	    char accept[64] = { 0 };
177	    if (make_accept_key(ws_key, accept, sizeof(accept)) < 0)
178	        return -1;
179	
180	    /* Send 101 */
181	    char resp[512];
182	    int rlen = snprintf(resp, sizeof(resp),
183	        "HTTP/1.1 101 Switching Protocols\r\n"
184	        "Upgrade: websocket\r\n"
185	        "Connection: Upgrade\r\n"
186	        "Sec-WebSocket-Accept: %s\r\n\r\n",
187	        accept);
188	    if (send(fd, resp, rlen, 0) != rlen)
189	        return -1;
190	
191	    /* Default chat_id from fd (may be overridden by first message) */
192	    snprintf(chat_id_out, chat_id_size, "ws_%d", fd);
193	    return 0;
194	}
