196	/* ── WS frame encode/decode ───────────────────────────────────── */
197	
198	/* Opcodes this server emits. Incoming frames are decoded separately. */
199	#define WS_OPCODE_TEXT   0x1
200	#define WS_OPCODE_BINARY 0x2
201	
202	/* Scratch for coalescing a frame's header and payload into one send(). Only
203	 * touched with s_clients_mtx held. Sized to cover a 3 KB audio frame plus
204	 * header; anything larger falls back to two sends.
205	 */
206	static unsigned char s_frame_scratch[4096];
207	
208	/**
209	 * Send one unfragmented frame (server → client, no masking).
210	 * Caller must hold s_clients_mtx.
211	 */
212	static int ws_send_frame_op(int fd, const void* payload, size_t len,
213	    int opcode)
214	{
215	    unsigned char hdr[10];
216	    int hdr_len = 0;
217	
218	    hdr[0] = (unsigned char)(0x80 | opcode); /* FIN + opcode */
219	    if (len < 126) {
220	        hdr[1] = (unsigned char)len;
221	        hdr_len = 2;
222	    } else if (len < 65536) {
223	        hdr[1] = 126;
224	        hdr[2] = (unsigned char)(len >> 8);
225	        hdr[3] = (unsigned char)(len & 0xFF);
226	        hdr_len = 4;
227	    } else {
228	        syslog(LOG_ERR, "[%s] Payload too large: %d\n", TAG, (int)len);
229	        return -1;
230	    }
231	
232	    /* Header and payload go out in a single send().
233	     *
234	     * Emitting them separately makes Nagle hold the payload back until the
235	     * header is acknowledged, while the peer's delayed ACK waits for a second
236	     * segment before acknowledging -- the two together stall each frame for
237	     * roughly the delayed-ACK timer. On a microphone stream that is fatal:
238	     * at 100 ms per frame it throttles delivery to about a third of the
239	     * capture rate, and the samples the reader never gets to are silently
240	     * overwritten by the DMA.
241	     */
242	    if (hdr_len + len <= sizeof(s_frame_scratch))
243	      {
244	        memcpy(s_frame_scratch, hdr, hdr_len);
245	        memcpy(s_frame_scratch + hdr_len, payload, len);
246	        if (send(fd, s_frame_scratch, hdr_len + len, 0) != hdr_len + (int)len)
247	          {
248	            return -1;
249	          }
250	
251	        return 0;
252	      }
253	
254	    /* Larger frames: still one send(), from the heap. Never two sends -- see
255	     * the note above about interleaving with other writers. */
256	    unsigned char* big = malloc(hdr_len + len);
257	    if (big == NULL)
258	      {
259	        syslog(LOG_ERR, "[%s] out of memory for %d byte frame\n", TAG,
260	            (int)(hdr_len + len));
261	        return -1;
262	      }
263	
264	    memcpy(big, hdr, hdr_len);
265	    memcpy(big + hdr_len, payload, len);
266	    int rc = (send(fd, big, hdr_len + len, 0) == hdr_len + (int)len) ? 0 : -1;
267	    free(big);
268	    return rc;
269	}
270	
271	/**
272	 * Send a text frame. Caller must hold s_clients_mtx.
273	 */
274	static int ws_send_frame(int fd, const char* payload, size_t len)
275	{
276	    return ws_send_frame_op(fd, payload, len, WS_OPCODE_TEXT);
277	}
