279	/**
280	 * Read and decode one WS frame; place text payload into buf (NUL-terminated).
281	 * Returns payload length on success, 0 on close frame, -1 on error.
282	 */
283	static int ws_recv_frame(int fd, char* buf, size_t buf_size)
284	{
285	    unsigned char b0, b1;
286	    if (recv(fd, &b0, 1, MSG_WAITALL) != 1)
287	        return -1;
288	    if (recv(fd, &b1, 1, MSG_WAITALL) != 1)
289	        return -1;
290	
291	    int opcode = b0 & 0x0F;
292	    bool masked = (b1 & 0x80) != 0;
293	    size_t plen = b1 & 0x7F;
294	
295	    if (opcode == 0x8)
296	        return 0; /* Close frame */
297	
298	    if (opcode == 0x9 || opcode == 0xA) {
299	        /* Ping (0x9) or Pong (0xA) — must consume payload before returning,
300	         * otherwise leftover bytes corrupt the next frame read. */
301	        if (plen == 126) {
302	            unsigned char ext[2];
303	            if (recv(fd, ext, 2, MSG_WAITALL) != 2)
304	                return -1;
305	            plen = ((size_t)ext[0] << 8) | ext[1];
306	        } else if (plen == 127) {
307	            return -1;
308	        }
309	
310	        unsigned char pp_mask[4] = { 0 };
311	        if (masked) {
312	            if (recv(fd, pp_mask, 4, MSG_WAITALL) != 4)
313	                return -1;
314	        }
315	
316	        if (plen > 125) {
317	            syslog(LOG_ERR,
318	                "[%s] Invalid control frame payload length: %d\n",
319	                TAG, (int)plen);
320	            return -1;
321	        }
322	
323	        /* Read full control payload so ping can be echoed in pong. */
324	        unsigned char ctrl_payload[125] = { 0 };
325	        if (plen > 0) {
326	            if (recv(fd, ctrl_payload, plen, MSG_WAITALL) != (int)plen)
327	                return -1;
328	
329	            if (masked) {
330	                for (size_t i = 0; i < plen; i++) {
331	                    ctrl_payload[i] ^= pp_mask[i % 4];
332	                }
333	            }
334	        }
335	
336	        /* Reply with pong if it was a ping.
337	         *
338	         * Assembled into one buffer and sent under s_clients_mtx: this runs on
339	         * the client thread while other threads (the microphone stream, agent
340	         * replies) write to the same socket, and a control frame that lands
341	         * between another frame's header and its payload desynchronises the
342	         * peer's parser. Coalescing also avoids the same Nagle/delayed-ACK
343	         * stall that splitting a frame across two sends causes.
344	         */
345	        if (opcode == 0x9) {
346	            unsigned char pong[2 + 125];
347	            size_t n = 0;
348	
349	            pong[n++] = 0x8A;
350	            pong[n++] = (unsigned char)plen;
351	            if (plen > 0) {
352	                memcpy(pong + n, ctrl_payload, plen);
353	                n += plen;
354	            }
355	
356	            pthread_mutex_lock(&s_clients_mtx);
357	            send(fd, pong, n, 0);
358	            pthread_mutex_unlock(&s_clients_mtx);
359	        }
360	        return -2;
361	    }
362	
363	    if (opcode != 0x1 && opcode != 0x2) {
364	        /* Unknown opcode — skip */
365	        return -2;
366	    }
367	
368	    if (plen == 126) {
369	        unsigned char ext[2];
370	        if (recv(fd, ext, 2, MSG_WAITALL) != 2)
371	            return -1;
372	        plen = ((size_t)ext[0] << 8) | ext[1];
373	    } else if (plen == 127) {
374	        syslog(LOG_ERR, "[%s] 64-bit frame length not supported\n", TAG);
375	        return -1;
376	    }
377	
378	    unsigned char mask_key[4] = { 0 };
379	    if (masked) {
380	        if (recv(fd, mask_key, 4, MSG_WAITALL) != 4)
381	            return -1;
382	    }
383	
384	    if (plen >= buf_size) {
385	        syslog(LOG_ERR, "[%s] Frame too large: %d\n", TAG, (int)plen);
386	        return -1;
387	    }
388	
389	    int received = 0;
390	    while ((size_t)received < plen) {
391	        int n = recv(fd, buf + received, plen - received, 0);
392	        if (n <= 0)
393	            return -1;
394	        received += n;
395	    }
396	
397	    if (masked) {
398	        for (size_t i = 0; i < plen; i++) {
399	            ((unsigned char*)buf)[i] ^= mask_key[i % 4];
400	        }
401	    }
402	
403	    buf[plen] = '\0';
404	    return (int)plen;
405	}
406	
407	/* ── Per-client thread ────────────────────────────────────────── */
408	
409	typedef struct {
410	    int fd;
411	} client_arg_t;
412	
413	static void* client_thread(void* arg)
414	{
415	    client_arg_t ca = *(client_arg_t*)arg;
416	    free(arg);
417	    int fd = ca.fd;
418	
419	    /* Peek HTTP headers to decide: REST API or WebSocket */
420	    char* peek_buf = malloc(2048);
421	    if (!peek_buf) {
422	        close(fd);
423	        return NULL;
424	    }
425	    int peek_total = 0;
426	    while (peek_total < 2048 - 1) {
427	        int n = recv(fd, peek_buf + peek_total,
428	            2048 - 1 - peek_total, 0);
429	        if (n <= 0) {
430	            free(peek_buf);
431	            close(fd);
432	            return NULL;
433	        }
434	        peek_total += n;
435	        peek_buf[peek_total] = '\0';
436	        if (strstr(peek_buf, "\r\n\r\n"))
437	            break;
438	    }
439	
440	    syslog(LOG_INFO, "[%s] fd=%d: %d bytes, first line: %.60s\n", TAG, fd,
441	        peek_total, peek_buf);
442	
443	    /* Try REST API (config/skills/logs) */
444	#ifdef CONFIG_AI_AGENT_REST_API
445	    if (api_try_handle(fd, peek_buf, peek_total)) {
446	        free(peek_buf);
447	        /* Graceful close only. SO_LINGER with l_linger=0 here used to send
448	         * an RST that discarded the response still in the send buffer,
449	         * so REST clients saw "Connection reset by peer" and no body. */
450	        shutdown(fd, SHUT_WR);
451	        close(fd);
452	        return NULL;
453	    }
454	#endif
455	
456	    /* Not REST API - proceed with WebSocket handshake using pre-read buffer */
457	    char chat_id[32];
458	    if (do_ws_handshake_ex(fd, peek_buf, peek_total,
459	            chat_id, sizeof(chat_id))
460	        != 0) {
461	        syslog(LOG_WARNING, "[%s] Handshake failed for fd=%d\n", TAG, fd);
462	        free(peek_buf);
463	        /* Answer plain-HTTP callers with a 400 instead of a silent close,
464	         * so the client sees a real response instead of a bare FIN/RST. */
465	        static const char bad[] =
466	            "HTTP/1.1 400 Bad Request\r\n"
467	            "Content-Type: text/plain\r\n"
468	            "Content-Length: 20\r\n"
469	            "Connection: close\r\n\r\n"
470	            "not a WebSocket peer\n";
471	        send(fd, bad, sizeof(bad) - 1, 0);
472	        shutdown(fd, SHUT_WR);
473	        close(fd);
474	        return NULL;
475	    }
476	    free(peek_buf);
477	
478	    /* Register client */
479	    pthread_mutex_lock(&s_clients_mtx);
480	    ws_client_t* client = add_client_locked(fd);
481	    if (!client) {
482	        pthread_mutex_unlock(&s_clients_mtx);
483	        syslog(LOG_WARNING, "[%s] Max clients reached, closing fd=%d\n", TAG, fd);
484	        /* Politely close */
485	        unsigned char close_frame[2] = { 0x88, 0x00 };
486	        send(fd, close_frame, 2, 0);
487	        close(fd);
488	        return NULL;
489	    }
490	    snprintf(client->chat_id, sizeof(client->chat_id), "%s", chat_id);
491	    pthread_mutex_unlock(&s_clients_mtx);
492	
493	    /* Send connect.challenge so Nodes can identify themselves */
494	#ifdef CONFIG_AI_AGENT_NODE
495	    node_manager_send_challenge(fd);
496	#endif
497	
498	    /* Read loop — stack-allocated so each client thread has its own buffer */
499	    char frame_buf[4096];
500	    while (s_running) {
501	        int n = ws_recv_frame(fd, frame_buf, sizeof(frame_buf));
502	        if (n < 0 && n != -2)
503	            break; /* -2 = ignored opcode, not an error */
504	        if (n == 0)
505	            break; /* clean close */
506	        if (n < 0)
507	            continue; /* ignored frame */
508	
509	        /* Try Node protocol first — if handled, skip chat processing */
510	#ifdef CONFIG_AI_AGENT_NODE
511	        if (node_manager_handle_message(fd, frame_buf, n))
512	            continue;
513	#endif
514	
515	        /* Parse JSON message */
516	        cJSON* root = cJSON_Parse(frame_buf);
517	        if (!root) {
518	            syslog(LOG_WARNING, "[%s] Invalid JSON from fd=%d (%d bytes): %.200s\n",
519	                TAG, fd, n, frame_buf);
520	            continue;
521	        }
522	
523	        cJSON* type_item = cJSON_GetObjectItem(root, "type");
524	        cJSON* content_item = cJSON_GetObjectItem(root, "content");
525	
526	        /* Microphone streaming control. These frames carry no content; they
527	         * switch this client's capture stream on and off. The reply, if any,
528	         * arrives asynchronously as binary PCM frames plus normal agent
529	         * responses.
530	         */
531	        if (cJSON_IsString(type_item)
532	            && (strcmp(type_item->valuestring, "mic_start") == 0
533	                || strcmp(type_item->valuestring, "mic_stop") == 0)) {
534	            bool want = (strcmp(type_item->valuestring, "mic_start") == 0);
535	            cJSON* n_item = cJSON_GetObjectItem(root, "samples");
536	            int samples = cJSON_IsNumber(n_item) ? (int)n_item->valuedouble : 0;
537	            syslog(LOG_INFO, "[%s] %s request from %s\n", TAG,
538	                type_item->valuestring, chat_id);
539	            cJSON_Delete(root);
540	            if (want)
541	                mic_stream_start(chat_id, samples);
542	            else
543	                mic_stream_stop();
544	            continue;
545	        }
546	
547	        if (cJSON_IsString(type_item) && strcmp(type_item->valuestring, "message") == 0 && cJSON_IsString(content_item)) {
548	
549	            /* Determine/update chat_id */
550	            cJSON* cid_item = cJSON_GetObjectItem(root, "chat_id");
551	            pthread_mutex_lock(&s_clients_mtx);
552	            ws_client_t* c = find_by_fd_locked(fd);
553	            if (c) {
554	                if (cJSON_IsString(cid_item)) {
555	                    strncpy(c->chat_id, cid_item->valuestring, sizeof(c->chat_id) - 1);
556	                }
557	                strncpy(chat_id, c->chat_id, sizeof(chat_id) - 1);
558	            }
559	            pthread_mutex_unlock(&s_clients_mtx);
560	
561	            syslog(LOG_INFO, "[%s] WS msg from %s: %.40s\n", TAG, chat_id,
562	                content_item->valuestring);
563	
564	            agent_msg_t msg = { 0 };
565	            strncpy(msg.channel, AGENT_CHAN_WEBSOCKET, sizeof(msg.channel) - 1);
566	            strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
567	            msg.content = strdup(content_item->valuestring);
568	            if (msg.content)
569	                message_bus_push_inbound(&msg);
570	        }
571	        cJSON_Delete(root);
572	    }
573	
574	    /* Notify node manager before removing client */
575	#ifdef CONFIG_AI_AGENT_NODE
576	    node_manager_on_disconnect(fd);
577	#endif
578	
579	    /* Remove and close */
580	    pthread_mutex_lock(&s_clients_mtx);
581	    remove_client_locked(fd);
582	    pthread_mutex_unlock(&s_clients_mtx);
583	
584	    return NULL;
585	}
