587	/* ── Accept loop ──────────────────────────────────────────────── */
588	
589	static void* accept_thread(void* arg)
590	{
591	    (void)arg;
592	    while (s_running) {
593	        struct pollfd pfd = { .fd = s_listen_fd, .events = POLLIN };
594	        int pr = poll(&pfd, 1, 500);
595	        if (pr <= 0)
596	            continue;
597	
598	        struct sockaddr_in addr;
599	        socklen_t addr_len = sizeof(addr);
600	        int cfd = accept(s_listen_fd, (struct sockaddr*)&addr, &addr_len);
601	        if (cfd < 0)
602	            continue;
603	
604	        syslog(LOG_INFO, "[%s] accepted fd=%d from %s:%d\n", TAG, cfd,
605	            inet_ntoa(addr.sin_addr), ntohs(addr.sin_port));
606	
607	        client_arg_t* ca = malloc(sizeof(client_arg_t));
608	        if (!ca) {
609	            close(cfd);
610	            continue;
611	        }
612	        ca->fd = cfd;
613	
614	        pthread_t tid;
615	        pthread_attr_t attr;
616	        pthread_attr_init(&attr);
617	        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
618	        pthread_attr_setstacksize(&attr, AGENT_WS_CLIENT_STACK);
619	        if (pthread_create(&tid, &attr, client_thread, ca) != 0) {
620	            free(ca);
621	            close(cfd);
622	        }
623	        pthread_attr_destroy(&attr);
624	    }
625	    return NULL;
626	}
