629	
630	int ws_server_start(void)
631	{
632	    memset(s_clients, 0, sizeof(s_clients));
633	
634	    s_listen_fd = socket(AF_INET, SOCK_STREAM, 0);
635	    if (s_listen_fd < 0) {
636	        syslog(LOG_ERR, "[%s] socket() failed\n", TAG);
637	        return ERROR;
638	    }
639	
640	    int opt = 1;
641	    setsockopt(s_listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
642	
643	    struct sockaddr_in addr = {
644	        .sin_family = AF_INET,
645	        .sin_port = htons(AGENT_WS_PORT),
646	        .sin_addr.s_addr = INADDR_ANY,
647	    };
648	
649	    if (bind(s_listen_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
650	        syslog(LOG_ERR, "[%s] bind() failed on port %d, errno=%d\n", TAG,
651	            AGENT_WS_PORT, errno);
652	        close(s_listen_fd);
653	        s_listen_fd = -1;
654	        return ERROR;
655	    }
656	
657	    if (listen(s_listen_fd, AGENT_WS_MAX_CLIENTS) < 0) {
658	        syslog(LOG_ERR, "[%s] listen() failed\n", TAG);
659	        close(s_listen_fd);
660	        s_listen_fd = -1;
661	        return ERROR;
662	    }
663	
664	    s_running = true;
665	
666	    pthread_t tid;
667	    pthread_attr_t attr;
668	    pthread_attr_init(&attr);
669	    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
670	    pthread_attr_setstacksize(&attr, AGENT_CLI_STACK);
671	    int rc = pthread_create(&tid, &attr, accept_thread, NULL);
672	    pthread_attr_destroy(&attr);
673	
674	    if (rc != 0) {
675	        syslog(LOG_ERR, "[%s] Failed to create accept thread\n", TAG);
676	        s_running = false;
677	        close(s_listen_fd);
678	        s_listen_fd = -1;
679	        return ERROR;
680	    }
681	
682	    syslog(LOG_INFO, "[%s] WebSocket server started on port %d\n", TAG,
683	        AGENT_WS_PORT);
684	    return OK;
685	}
686	
687	int ws_server_send(const char* chat_id, const char* text)
688	{
689	    if (s_listen_fd < 0 || !s_running)
690	        return ERROR;
691	
692	    /* Build JSON response */
693	    cJSON* resp = cJSON_CreateObject();
694	    cJSON_AddStringToObject(resp, "type", "response");
695	    cJSON_AddStringToObject(resp, "content", text);
696	    cJSON_AddStringToObject(resp, "chat_id", chat_id);
697	    char* json_str = cJSON_PrintUnformatted(resp);
698	    cJSON_Delete(resp);
699	    if (!json_str)
700	        return ERROR;
701	
702	    pthread_mutex_lock(&s_clients_mtx);
703	    ws_client_t* client = find_by_chat_id_locked(chat_id);
704	    int rc = -1;
705	    if (client) {
706	        rc = ws_send_frame(client->fd, json_str, strlen(json_str));
707	        if (rc != 0) {
708	            syslog(
709	                LOG_WARNING,
710	                "[%s] Send failed to %s (fd will be cleaned up by client thread)\n",
711	                TAG, chat_id);
712	            /* Don't remove/close here — the client_thread owns the fd lifecycle.
713	             * The recv() in client_thread will fail and trigger cleanup. */
714	        }
715	    } else {
716	        syslog(LOG_WARNING, "[%s] No WS client for chat_id=%s\n", TAG, chat_id);
717	    }
718	    pthread_mutex_unlock(&s_clients_mtx);
719	
720	    free(json_str);
721	    return (client == NULL) ? ERROR : (rc == 0 ? OK : ERROR);
722	}
723	
724	/**
725	 * Send a pre-built JSON control frame to a client.
726	 *
727	 * Unlike ws_server_send() this does not wrap the payload in a chat response
728	 * envelope, which is what control and status frames need.
729	 */
730	int ws_server_send_json(const char* chat_id, const char* json)
731	{
732	    if (s_listen_fd < 0 || !s_running || json == NULL)
733	        return ERROR;
734	
735	    pthread_mutex_lock(&s_clients_mtx);
736	    ws_client_t* client = find_by_chat_id_locked(chat_id);
737	    int rc = -1;
738	    if (client) {
739	        rc = ws_send_frame(client->fd, json, strlen(json));
740	    }
741	    pthread_mutex_unlock(&s_clients_mtx);
742	
743	    return (client == NULL) ? ERROR : (rc == 0 ? OK : ERROR);
744	}
745	
746	/**
747	 * Push one binary frame to a client.
748	 *
749	 * Used for raw stream payloads (currently microphone PCM) that would be
750	 * wasteful and fragile to carry as base64 inside JSON. Frames larger than
751	 * 65535 bytes are rejected by the encoder, so callers must chunk.
752	 */
753	int ws_server_send_binary(const char* chat_id, const void* data, size_t len)
754	{
755	    if (s_listen_fd < 0 || !s_running || data == NULL || len == 0)
756	        return ERROR;
757	
758	    pthread_mutex_lock(&s_clients_mtx);
759	    ws_client_t* client = find_by_chat_id_locked(chat_id);
760	    int rc = -1;
761	    if (client) {
762	        rc = ws_send_frame_op(client->fd, data, len, WS_OPCODE_BINARY);
763	    }
764	    pthread_mutex_unlock(&s_clients_mtx);
765	
766	    return (client == NULL) ? ERROR : (rc == 0 ? OK : ERROR);
767	}
768	
769	int ws_server_stop(void)
770	{
771	    s_running = false;
772	    if (s_listen_fd >= 0) {
773	        close(s_listen_fd);
774	        s_listen_fd = -1;
775	    }
776	    syslog(LOG_INFO, "[%s] WebSocket server stopped\n", TAG);
777	    return OK;
778	}
