17	/* Bring-up commands for the on-board MEMS microphone (SF32LB52 AUDCODEC ADC).
18	 *
19	 * The capture path has no other openvela reference implementation, so these
20	 * commands exist to answer the two questions that come up first when it does
21	 * not behave: is the microphone picking anything up at all (mic_test), and
22	 * what is actually coming out of the DMA (mic_raw, mic_dump). */
23	
24	#include "channels/cmd_mic.h"
25	#include "agent_compat.h"
26	
27	#include "sf32lb_audcodec.h"
28	
29	#include <stdlib.h>
30	#include <string.h>
31	#include <time.h>
32	#include <unistd.h>
33	
34	#define MIC_TEST_SAMPLE_RATE 16000
35	#define MIC_BLOCK_MS         100
36	#define MIC_BLOCK_SAMPLES    (MIC_TEST_SAMPLE_RATE / (1000 / MIC_BLOCK_MS))
37	
38	#define MIC_TEST_MAX_SECONDS 120
39	
40	/* mic_test [seconds] [pll|xtal] [0|1]
41	 *
42	 * The clock source and ADC channel are selectable because neither is settled
43	 * for this board: the HAL's own reference ADC_CFG value (0x508) selects the
44	 * crystal, while the analog front-end helper defaults to the PLL, and which
45	 * ADC channel the on-board microphone lands on is not documented anywhere in
46	 * the tree.
47	 */
48	void cmd_mic_test(int argc, char** argv)
49	{
50	    int seconds = (argc >= 2) ? atoi(argv[1]) : 5;
51	    enum sf32lb_audio_clk_e clk = SF32LB_AUDIO_CLK_PLL;
52	    int channel = 0;
53	    int volume = SF32LB_AUDIO_DEFAULT_VOLUME;
54	    int blocks;
55	    int16_t* buf;
56	    int ret;
57	    int i;
58	
59	    if (seconds <= 0) {
60	        seconds = 5;
61	    }
62	
63	    if (seconds > MIC_TEST_MAX_SECONDS) {
64	        seconds = MIC_TEST_MAX_SECONDS;
65	    }
66	
67	    if (argc >= 3) {
68	        clk = (strcmp(argv[2], "xtal") == 0) ? SF32LB_AUDIO_CLK_XTAL
69	                                             : SF32LB_AUDIO_CLK_PLL;
70	    }
71	
72	    if (argc >= 4) {
73	        channel = atoi(argv[3]) ? 1 : 0;
74	    }
75	
76	    if (argc >= 5) {
77	        volume = atoi(argv[4]);
78	    }
79	
80	    if (argc >= 7) {
81	        sf32lb_audcodec_set_clk((uint8_t)atoi(argv[5]), (uint8_t)atoi(argv[6]));
82	    }
83	
84	    if (sf32lb_audcodec_is_open()) {
85	        printf("mic_test: capture already running, restarting\n");
86	        sf32lb_audcodec_close();
87	        usleep(50000);
88	    }
89	
90	    ret = sf32lb_audcodec_open_ex(MIC_TEST_SAMPLE_RATE, clk, channel, volume);
91	    if (ret < 0) {
92	        printf("mic_test: open failed (%d)\n", ret);
93	        return;
94	    }
95	
96	    buf = malloc(MIC_BLOCK_SAMPLES * sizeof(int16_t));
97	    if (buf == NULL) {
98	        printf("mic_test: out of memory\n");
99	        sf32lb_audcodec_close();
100	        return;
101	    }
102	
103	    {
104	        uint8_t div, osr;
105	        sf32lb_audcodec_get_clk(&div, &osr);
106	        printf("mic_test: %d s, %d ms blocks, %s clock, ADC ch%d, %d dB, "
107	               "clk_div=%d osr_sel=%d -- make some noise\n"
108	               "          (block timing is nominal; check mic_rate for the "
109	               "true sample rate)\n",
110	            seconds, MIC_BLOCK_MS,
111	            (clk == SF32LB_AUDIO_CLK_XTAL) ? "xtal" : "pll", channel, volume,
112	            div, osr);
113	    }
114	
115	    /* Print what the block actually latched, not what we asked for. */
116	    cmd_mic_dump(0, NULL);
117	
118	    /* Let the analog front end and the DMA settle before the first read. */
119	    usleep(200000);
120	
121	    blocks = seconds * (1000 / MIC_BLOCK_MS);
122	
123	    for (i = 0; i < blocks; i++) {
124	        struct sf32lb_audio_stats_s stats;
125	        ssize_t n = sf32lb_audcodec_read(buf, MIC_BLOCK_SAMPLES);
126	        int peak;
127	
128	        if (n < 0) {
129	            printf("mic_test: read failed (%d)\n", (int)n);
130	            break;
131	        }
132	
133	        sf32lb_audcodec_analyze(buf, MIC_BLOCK_SAMPLES, &stats);
134	        peak = (stats.min < 0 ? -stats.min : stats.min);
135	        if (stats.max > peak) {
136	            peak = stats.max;
137	        }
138	
139	        printf("[mic] %5d ms  rms=%-6ld peak=%-6d min=%-6d max=%-6d "
140	               "mean=%-5ld zero=%zu\n",
141	            (i + 1) * MIC_BLOCK_MS, (long)stats.rms, peak,
142	            stats.min, stats.max, (long)stats.mean, stats.nzero);
143	    }
144	
145	    free(buf);
146	    sf32lb_audcodec_close();
147	    printf("mic_test: done\n");
148	}
