150	void cmd_mic_raw(int argc, char** argv)
151	{
152	    int words = (argc >= 2) ? atoi(argv[1]) : 32;
153	    uint32_t raw[128];
154	    ssize_t n;
155	    int ret;
156	    int i;
157	
158	    if (words <= 0 || words > (int)(sizeof(raw) / sizeof(raw[0]))) {
159	        words = 32;
160	    }
161	
162	    if (!sf32lb_audcodec_is_open()) {
163	        ret = sf32lb_audcodec_open(MIC_TEST_SAMPLE_RATE);
164	        if (ret < 0) {
165	            printf("mic_raw: open failed (%d)\n", ret);
166	            return;
167	        }
168	    }
169	
170	    usleep(200000);
171	    n = sf32lb_audcodec_read_raw(raw, words);
172	    if (n < 0) {
173	        printf("mic_raw: read failed (%d)\n", (int)n);
174	        sf32lb_audcodec_close();
175	        return;
176	    }
177	
178	    printf("mic_raw: %d DMA words "
179	           "(lo16 / hi16 both shown -- tells us where the sample sits)\n",
180	        (int)n);
181	
182	    for (i = 0; i < (int)n; i++) {
183	        printf("  [%3d] 0x%08lx  lo=%6d  hi=%6d\n", i,
184	            (unsigned long)raw[i],
185	            (int)(int16_t)(raw[i] & 0xffff),
186	            (int)(int16_t)(raw[i] >> 16));
187	    }
188	}
189	
190	void cmd_mic_dump(int argc, char** argv)
191	{
192	    struct sf32lb_audcodec_regs_s r;
193	
194	    (void)argc;
195	    (void)argv;
196	
197	    if (sf32lb_audcodec_get_regs(&r) < 0) {
198	        printf("mic_dump: capture is not open (run mic_test first)\n");
199	        return;
200	    }
201	
202	    /* Decoded against the vendor bit definitions so the values can be read
203	     * without a register map to hand:
204	     *   ADC_CFG   bits0-2 OSR_SEL, bits3-4 OP_MODE, bit6 CLK_SRC_SEL,
205	     *             bits8-15 CLK_DIV
206	     *   CFG       bit0 ADC_ENABLE, bit1 DAC_ENABLE
207	     *   CH0/CH1   bit0 ENABLE, bit7 DMA_EN, bits8-11 ROUGH_VOL, bit16 FMT
208	     * The reference the HAL documents is ADC_CFG == 0x508.
209	     */
210	    printf("mic_dump: AUDCODEC registers\n");
211	    printf("  CFG         = 0x%08lx  (adc_en=%lu dac_en=%lu)\n",
212	        (unsigned long)r.cfg,
213	        (unsigned long)(r.cfg & 1), (unsigned long)((r.cfg >> 1) & 1));
214	    printf("  ADC_CFG     = 0x%08lx  (osr=%lu opmode=%lu clksrc=%lu div=%lu)\n",
215	        (unsigned long)r.adc_cfg,
216	        (unsigned long)(r.adc_cfg & 0x7),
217	        (unsigned long)((r.adc_cfg >> 3) & 0x3),
218	        (unsigned long)((r.adc_cfg >> 6) & 0x1),
219	        (unsigned long)((r.adc_cfg >> 8) & 0xff));
220	    printf("  ADC_CH0_CFG = 0x%08lx  (en=%lu dma_en=%lu vol=%lu fmt=%lu)\n",
221	        (unsigned long)r.adc_ch0_cfg,
222	        (unsigned long)(r.adc_ch0_cfg & 1),
223	        (unsigned long)((r.adc_ch0_cfg >> 7) & 1),
224	        (unsigned long)((r.adc_ch0_cfg >> 8) & 0xf),
225	        (unsigned long)((r.adc_ch0_cfg >> 16) & 1));
226	    printf("  ADC_CH1_CFG = 0x%08lx\n", (unsigned long)r.adc_ch1_cfg);
227	    printf("  ADC_ANA_CFG = 0x%08lx  (micbias_en=%lu)\n",
228	        (unsigned long)r.adc_ana_cfg,
229	        (unsigned long)((r.adc_ana_cfg >> 1) & 1));
