def pty_write_all(fd, data, deadline=10.0):
    """Write every byte to the PTY.

    os.write() on a non-blocking PTY stops at the tty's input queue and
    returns the count it took, and the bytes it did not take are gone. The
    queue holds a few KB while the serial side hands over as much as 64 KB at
    once, so under a continuous stream this fires constantly -- and the loss
    is invisible here: the PPP layer above sees a corrupted frame and drops
    it, which looks like a flaky link rather than a short write.

    Waits for room instead of dropping. Gives up after 'deadline' seconds so
    that a peer which has stopped draining cannot wedge the relay loop.
    """
    view = memoryview(data)
    end = time.monotonic() + deadline

    while view:
        try:
            n = os.write(fd, view)
            view = view[n:]
            continue
        except BlockingIOError:
            pass
        except OSError as exc:
            if exc.errno != errno.EIO:
                print(f"[bridge] pty write failed: {exc}", flush=True)
            return False

        if time.monotonic() >= end:
            print(f"[bridge] pty stalled, {len(view)} bytes dropped", flush=True)
            return False

        try:
            select.select([], [fd], [], 0.2)
        except (OSError, ValueError):
            return False

    return True

