def _norm(t):
    return " ".join(t.split())

def _mem_used_free(tool_msgs):
    """(total, used, free) in bytes from the `free` table, or None."""
    for m in tool_msgs:
        t = _tool_text(m)
        if "total used free" not in _norm(t):
            continue
        for row in t.splitlines():
            parts = row.split()
            if len(parts) >= 3 and parts[0].isdigit():
                return int(parts[0]), int(parts[1]), int(parts[2])
    return None

def _uptime_secs(tool_msgs):
    for m in tool_msgs:
        mm = re.search(r"Uptime:\s*([0-9.]+)", _tool_text(m))
        if mm:
            return float(mm.group(1))
    return None

def _data_disk(tool_msgs):
    """(used, total) strings for /data from the `df` table, or None."""
    for m in tool_msgs:
        t = _tool_text(m)
        if "Filesystem" not in t:
            continue
        for row in t.splitlines():
            if "/data" in row:
                parts = row.split()
                if len(parts) >= 4:
                    return parts[2], parts[1]
    return None

def _task_lines(tool_msgs):
    for m in tool_msgs:
        t = _tool_text(m)
        if re.search(r"\bpppd\b|\bnsh\b", t):
            return [r for r in t.splitlines() if r.strip()]
    return []
