/* Watch the packet pool.
 *
 * When the device "stops responding" under load, the audio keeps flowing and
 * only *new* things fail -- ping, fresh WebSocket handshakes -- while
 * established connections carry on. That is the shape of a pool running dry
 * rather than a hang: existing connections already hold their buffers, new
 * allocations cannot get any. Printed only when it actually gets low, so the
 * console stays quiet in normal running.
 *
 * Bring-up instrumentation -- remove when the hang is understood.
 */

static void mic_check_iob(void)
{
    static int  s_low_water = CONFIG_IOB_NBUFFERS;
    static bool s_warned;
    int avail = iob_navail(false);

    if (avail < s_low_water) {
        s_low_water = avail;
    }

    if (avail < 64 && !s_warned) {
        s_warned = true;
        _err("mic_stream: IOB POOL LOW: %d of %d free (low water %d)\n",
             avail, CONFIG_IOB_NBUFFERS, s_low_water);
    } else if (avail > 128 && s_warned) {
        s_warned = false;
        _err("mic_stream: IOB pool recovered: %d free\n", avail);
    }
}

