/* Stall watchdog, armed only while streaming.
 *
 * When the device stops responding it does so silently: no assert, no fault,
 * nothing on the console, and the network simply goes quiet. NuttX only dumps
 * task state when something crashes, so a hang leaves no evidence at all --
 * which is why it has stayed undiagnosed.
 *
 * This manufactures the evidence. The stream is the device's most regular
 * activity, so if it stops making progress for this long something is stuck;
 * the watchdog fires from the timer interrupt, which runs whatever else the
 * system is doing, and panics deliberately to get the full task dump.
 *
 * Bring-up instrumentation -- remove when the hang is understood.
 */

#define MIC_STALL_DUMP_S 15

static struct wdog_s s_stall_wd;
static bool          s_stall_wd_ready;

static void mic_stall_dump(wdparm_t arg)
{
    (void)arg;

    /* Report, do not kill.
     *
     * An earlier version called PANIC() here to force a task dump, which is
     * the only way to see inside a hang -- and it worked, twice, and pointed
     * at pppd consuming the CPU while the audio thread never ran. But a
     * watchdog that turns a *slow* device into a *dead* one is a worse fault
     * than the one it watches for: it fired while audio was still trickling
     * out. Reporting is the safe half; if a dump is wanted again, panic here
     * deliberately and accept that the device stops.
     */
    _err("mic_stream: no audio progress for %d s\n", MIC_STALL_DUMP_S);
}

static void mic_stall_arm(void)
{
    /* s_stall_wd is static, so it is already in the all-NULL state
     * wd_initialize() would put it in, and wd_start() fills in the rest. */

    s_stall_wd_ready = true;

    /* Restarts the timer if it is already running, which is what we want:
     * each frame of audio pushes the deadline out. */
    wd_start(&s_stall_wd, SEC2TICK(MIC_STALL_DUMP_S), mic_stall_dump, 0);
}

static void mic_stall_disarm(void)
{
    if (s_stall_wd_ready) {
        wd_cancel(&s_stall_wd);
    }
}

/* Watch the packet pool.
 *
 * When the device "stops responding" under load, the audio keeps flowing and
 * only *new* things fail -- ping, fresh WebSocket handshakes -- while
 * established connections carry on. That is the shape of a pool running dry
 * rather than a hang: existing connections already hold their buffers, new
 * allocations cannot get any. Printed only when it actually gets low, so the
 * console stays quiet in normal running.
 *
 * Bring-up instrumentation -- remove when the hang is understood.
 */

static void mic_check_iob(void)
{
    static int  s_low_water = CONFIG_IOB_NBUFFERS;
    static bool s_warned;
    int avail = iob_navail(false);

    if (avail < s_low_water) {
        s_low_water = avail;
    }

    if (avail < 64 && !s_warned) {
        s_warned = true;
        _err("mic_stream: IOB POOL LOW: %d of %d free (low water %d)\n",
             avail, CONFIG_IOB_NBUFFERS, s_low_water);
    } else if (avail > 128 && s_warned) {
        s_warned = false;
        _err("mic_stream: IOB pool recovered: %d free\n", avail);
    }
}

