    if (len == 0 || (len == 1 && line[0] == '\n')) {
        if (off == 0) {
            continue;
        }
        break;
    }

    /* A section header ends it too */
    if (len >= 2 && line[0] == '#' && line[1] == '#') {
        break;
    }

